/** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure (in whole cents) by the sheet's today:
 *  for each full 30 days past its due-by plus its grade's grace days, the late percent in force on that boundary date
 *  (that day plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it (compounding),
 *  rounded as the claim rounds, added up. A correction (a negative amount) gains none, nor does a claim whose late
 *  charge was waived. */
export function lateChargeCents(
  c: { amount: string; date: string; dueBy: string; status: ClaimStatus; deferredUntil: string | null; waived?: boolean },
  figureCents: number,
  sheet: DueTerms,
  graceDays = 0,
): number {
  if (cents(c.amount) < 0 || c.waived || !isOverdue(c, sheet.today, graceDays)) return 0;
  const from = addDays(c.dueBy, graceDays);
  const days = (Date.parse(sheet.today) - Date.parse(from)) / 86_400_000;
  const periods = Math.floor(days / 30);
  const halfUp = roundsHalfUp(c.date, sheet);
  let charge = 0;
  for (let k = 1; k <= periods; k++) {
    const boundary = addDays(from, k * 30);
    charge += dueCents(figureCents + charge, latePctOn(sheet, boundary), halfUp);
  }
  return charge;
}

/** A claim's due in whole cents: the figure fixed when it was settled, else the figure its person's
 *  last statement binds it to (none: n/a), else its amount at its grade's rate in force on its date as the claim takes it (the sheet's own, else its nearest ancestor's) raised
 *  to the floor in force on its date (a correction is not), with any late charge worked out on that figure added on top
 *  of it; null when it has none. Its live
 *  figure rounds by `roundsOn`: its date, or for a correction the date of the claim it corrects. `grade` is its
 *  person's grade in force on its date, whose grace days delay its late charge. */
export function claimDueCents(
  c: { id?: number; amount: string; date: string; dueBy: string; status: ClaimStatus; deferredUntil: string | null; settledDue: string | null; stated: boolean; statedDue: string | null; statedLate?: string | null; waived?: boolean },
  gradeRates: RateLine,
  sheet: DueTerms,
  roundsOn: string,
  grade: Grade,
): number | null {
  if (c.settledDue !== null) return cents(c.settledDue);
  let figure: number;
  if (c.stated) {
    // A statement binds the claim to its figure then, or to none (n/a).
    if (c.statedDue === null) return null;
    figure = cents(c.statedDue);
  } else {
    const rate = rateOnLine(gradeRates, c.date, c.id);
    if (rate === undefined) return null;
    figure = dueCents(cents(c.amount), rate, roundsHalfUp(roundsOn, sheet));
    // The floor is applied before the late charge, which is worked out on the floored figure.
    if (cents(c.amount) >= 0) figure = Math.max(figure, cents(floorOn(sheet, c.date)));
  }
  // A statement binds the late charge with the figure: while bound, it no longer follows the sheet's today.
  const boundLate = c.stated && c.statedLate != null ? c.statedLate : null;
  const charges = boundLate !== null && (c.status === 'OPEN' || c.status === 'PENDING')
    && !isDeferred(c, sheet.today) && cents(c.amount) >= 0 && !c.waived;
  const late = boundLate === null ? lateChargeCents(c, figure, sheet, graceOn(sheet.settings, grade, c.date))
    : charges ? cents(boundLate) : 0;
  return figure + late;
}


